/* UTF-8 Decoder */
static inline uint32_t ds_utf8_next(const char **ptr) {
    const unsigned char *p = (const unsigned char *)*ptr;
    uint32_t cp = 0;
    if (!p || !*p) return 0;
    
    if (*p < 0x80) {
        cp = *p++;
    } else if ((*p & 0xE0) == 0xC0) {
        if ((p[1] & 0xC0) == 0x80) {
            cp = ((*p & 0x1F) << 6) | (p[1] & 0x3F);
            p += 2;
        } else {
            cp = *p++;
        }
    } else if ((*p & 0xF0) == 0xE0) {
        if ((p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80) {
            cp = ((*p & 0x0F) << 12) | ((p[1] & 0x3F) << 6) | (p[2] & 0x3F);
            p += 3;
        } else {
            cp = *p++;
        }
    } else if ((*p & 0xF8) == 0xF0) {
        if ((p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80 && (p[3] & 0xC0) == 0x80) {
            cp = ((*p & 0x07) << 18) | ((p[1] & 0x3F) << 12) | ((p[2] & 0x3F) << 6) | (p[3] & 0x3F);
            p += 4;
        } else {
            cp = *p++;
        }
    } else {
        cp = *p++;
    }
    *ptr = (const char *)p;
    return cp;
}

static inline const DS_GlyphData *ds_get_glyph(uint32_t cp) {
    if (cp < 128) {
        return &ds_font_ascii[cp];
    }
    if (cp >= 0x0400 && cp <= 0x045F) {
        return &ds_font_cyrillic[cp - 0x0400];
    }
    for (size_t i = 0; ds_font_special[i].cp != 0; ++i) {
        if (ds_font_special[i].cp == cp) {
            return &ds_font_special[i].glyph;
        }
    }
    /* Fallback to question mark '?' */
    return &ds_font_ascii[63];
}

static inline int ds_measure_text(const char *string) {
    if (!string) return 0;
    int total_width = 0;
    const char *p = string;
    while (*p) {
        uint32_t cp = ds_utf8_next(&p);
        if (cp == 0) break;
        const DS_GlyphData *g = ds_get_glyph(cp);
        total_width += g->width + 1;
    }
    return total_width > 0 ? total_width - 1 : 0;
}

static inline int ds_measure_text_scaled(const char *string, float scale) {
    int w = ds_measure_text(string);
    return (int)(w * scale + 0.5f);
}

/* Core font rendering with clipping, variable width, and smooth pixel writing */
static inline void ds_render_text(
    uint32_t *pixels, int width, int height, int stride,
    const char *string, float start_x, float start_y, uint32_t color, float scale
) {
    if (!pixels || !string || width <= 0 || height <= 0 || stride < width) return;
    if (scale <= 0.0f) scale = 1.0f;
    
    int cur_x = (int)(start_x + 0.5f);
    int cur_y = (int)(start_y + 0.5f);
    const char *p = string;
    
    /* Ensure non-zero alpha in destination pixel if 0x00RRGGBB passed */
    uint32_t render_color = color;
    if ((render_color & 0xFF000000) == 0) {
        render_color |= 0xFF000000;
    }
    
    int is_1x = (scale > 0.99f && scale < 1.01f);
    
    while (*p) {
        uint32_t cp = ds_utf8_next(&p);
        if (cp == 0) break;
        if (cp == '\n') {
            cur_x = (int)(start_x + 0.5f);
            cur_y += (int)(DS_FONT_HEIGHT * scale * 1.2f + 0.5f);
            continue;
        }
        
        const DS_GlyphData *g = ds_get_glyph(cp);
        int gw = g->width;
        
        if (is_1x) {
            for (int r = 0; r < 16; ++r) {
                int py = cur_y + r;
                if (py < 0 || py >= height) continue;
                uint16_t row_bits = g->rows[r];
                if (!row_bits) continue;
                
                uint32_t *line = pixels + py * stride;
                for (int c = 0; c < gw; ++c) {
                    if ((row_bits >> (15 - c)) & 1) {
                        int px = cur_x + c;
                        if (px >= 0 && px < width) {
                            line[px] = render_color;
                        }
                    }
                }
            }
            cur_x += gw + 1;
        } else {
            int scaled_w = (int)(gw * scale + 0.5f);
            int scaled_h = (int)(16 * scale + 0.5f);
            
            for (int sy = 0; sy < scaled_h; ++sy) {
                int py = cur_y + sy;
                if (py < 0 || py >= height) continue;
                int src_r = (int)(sy / scale);
                if (src_r >= 16) src_r = 15;
                uint16_t row_bits = g->rows[src_r];
                if (!row_bits) continue;
                
                uint32_t *line = pixels + py * stride;
                for (int sx = 0; sx < scaled_w; ++sx) {
                    int src_c = (int)(sx / scale);
                    if (src_c >= gw) src_c = gw - 1;
                    if ((row_bits >> (15 - src_c)) & 1) {
                        int px = cur_x + sx;
                        if (px >= 0 && px < width) {
                            line[px] = render_color;
                        }
                    }
                }
            }
            cur_x += scaled_w + (int)(scale + 0.5f);
        }
    }
}

